extended_properties.sql:
SELECT s.name AS schema_name,o.name AS object_name,ep.minor_id,ep.name AS property_name,CONVERT(nvarchar(4000),ep.value) AS property_value
FROM sys.objects o JOIN sys.schemas s ON s.schema_id=o.schema_id JOIN sys.extended_properties ep ON ep.class=1 AND ep.major_id=o.object_id
WHERE o.type IN ('U','V') AND o.name IN ({object_names}) ORDER BY s.name,o.name,ep.minor_id,ep.name;
